import { readFile, readdir, writeFile } from 'node:fs/promises'

// The migrations remain authoritative. This file prepares a single fresh-project
// installation script for Supabase Dashboard > SQL Editor, without Docker.
const directory = new URL('../supabase/migrations/', import.meta.url)
const files = (await readdir(directory)).filter((name) => /^\d+_.+\.sql$/.test(name)).sort()
if (!files.length) throw new Error('No SQL migrations found')

const parts = [
  '-- GENERATED by npm run db:bundle. Edit migrations, then regenerate this file.',
  '-- Fresh Supabase project only. Run the entire file once in the SQL Editor.',
  '-- Existing public tables cause a rollback; this script does not drop your data.',
  'begin;',
  `do $setup_preflight$
begin
 if exists(select 1 from pg_tables where schemaname='public') then
  raise exception 'Setup requires an empty public schema. Existing tables were detected; no setup changes have been applied. Use a fresh project or review an incremental migration.';
 end if;
end $setup_preflight$;`,
]
for (const file of files) {
  parts.push(`\n-- ==================== ${file} ====================\n`)
  parts.push((await readFile(new URL(file, directory), 'utf8')).trimEnd())
}
parts.push('\ncommit;\n')
await writeFile(new URL('../supabase/setup.sql', import.meta.url), parts.join('\n'))
console.log(`Prepared supabase/setup.sql from ${files.length} migrations.`)
